/* @lc app=leetcode id=2801 lang=kotlin */ class Solution { fun f(s: String, i: Int, last: Int, tight: Boolean, st: Boolean, m: HashMap<List<Any>, Long>): Long = if (i == s.length) (if (st) 1L else 0L) else m.getOrPut(listOf(i, last, tight, st)) { (0..(if (tight) s[i] - '0' else 9)).sumOf { d -> if (!st && d == 0) f(s, i + 1, 0, tight && d == s[i] - '0', false, m) else if (!st || Math.abs(d - last) == 1) f(s, i + 1, d, tight && d == s[i] - '0', true, m) else 0L } % 1_000_000_007 } fun countSteppingNumbers(low: String, high: String): Int = ((f(high, 0, 0, true, false, HashMap()) - f(low, 0, 0, true, false, HashMap()) + (if (low.zipWithNext().all { (a, b) -> Math.abs(a - b) == 1 }) 1 else 0) + 1_000_000_007) % 1_000_000_007).toInt() }